# (LISTEN_FLAG moved to the USER CONFIGURATION section near the top of this file.)
# (RELISTEN_FLAG moved to the USER CONFIGURATION section near the top of this file.)


def parse_listen_segment(text):
    """Read [start-end], [start:end] or [start end], in seconds.
    Reject reversed/empty ranges rather than silently analysing a whole song.
    """
    if not text:
        return text, None
    m = re.search(r"\[\s*(\d+(?:\.\d+)?)(?:\s*[-:]\s*|\s+)(\d+(?:\.\d+)?)\s*\]", text)
    if not m:
        return text, None
    start, end = float(m.group(1)), float(m.group(2))
    if not math.isfinite(start) or not math.isfinite(end) or end <= start:
        raise ValueError("Excerpt end must be greater than start (seconds).")
    return (text[:m.start()] + " " + text[m.end():]).strip(), (start, end)


def crop_audio_segment(path, start, end):
    """Crop local audio or a direct audio URL; never return the uncropped source.
    Decode a frame to reject a header-only WAV (for example, a range past EOF).
    """
    if not (math.isfinite(start) and math.isfinite(end) and 0 <= start < end):
        raise ValueError("Invalid excerpt range.")
    out = tempfile.NamedTemporaryFile(suffix=".wav", delete=False)
    out.close()
    try:
        result = subprocess.run([
            "ffmpeg", "-y", "-nostdin", "-hide_banner", "-loglevel", "error",
            "-ss", str(start), "-i", str(path), "-t", str(end - start),
            "-c:a", "pcm_s16le", out.name,
        ], capture_output=True, text=True, timeout=120)
        if result.returncode != 0:
            raise RuntimeError("ffmpeg could not decode the requested excerpt")
        probe = subprocess.run([
            "ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error",
            "-i", out.name, "-t", "0.01", "-f", "s16le", "pipe:1",
        ], capture_output=True, timeout=30)
        if probe.returncode != 0 or not probe.stdout:
            raise RuntimeError("The requested excerpt contains no decodable audio")
        return out.name
    except Exception as exc:
        try:
            os.remove(out.name)
        except OSError:
            pass
        raise RuntimeError(f"Excerpt was not analysed: {exc}") from exc
