_SCRIPT_LANGS = (("ko", r"[가-힯ᄀ-ᇿ]"), ("ja", r"[぀-ヿ]"), ("zh", r"[一-鿿]"),
                 ("ru", r"[Ѐ-ӿ]"), ("el", r"[Ͱ-Ͽ]"), ("ar", r"[؀-ۿ]"),
                 ("he", r"[֐-׿]"), ("hi", r"[ऀ-ॿ]"), ("th", r"[฀-๿]"))
_ARTIST_ORIGIN_CACHE = {}
_STYLE_ITEM_RE = re.compile(r"\s*(.+?) \(([^()]+)\) (\d+)%\s*$")
_STYLE_LED_TAG = "(style-led)"
_ERA_CHECK_HEAD = "ERA CHECK:"


def _style_norm(label):
    x = re.sub(r"\(.*?\)", "", str(label or "").lower()).strip()
    x = re.sub(r"\s+", " ", x)
    return _STYLE_LABEL_SYNONYMS.get(x, x)


def _style_families(label):
    t = _style_norm(label)
    return {f for f, keys in _STYLE_FAMILY_KEYS if any(k in t for k in keys)}


def _style_label(style, parent=""):
    """Conversation label for a Discogs style, or None."""
    if parent in _STYLE_NOT_GENRE_PARENTS:
        return None
    if style in _STYLE_LABELS:
        return _STYLE_LABELS[style]
    return style.lower()


def _style_signal_items(text):
    """[(label, prob)] from the last DISCOGS STYLE SIGNAL 'styles heard' line, same-named
    styles merged (strongest kept), non-genre styles dropped. [] when absent or none clear."""
    heard = _style_signal_heard(text)
    if not heard:
        return []
    out = {}
    for part in heard.split(";"):
        m = _STYLE_ITEM_RE.match(part)
        if not m:
            continue
        lab = _style_label(m.group(1).strip(), m.group(2).strip())
        if lab is None:
            continue
        p = int(m.group(3)) / 100.0
        if p > out.get(lab, (0.0, 0))[0]:
            out[lab] = (p, len(out))
    return [(l, v[0]) for l, v in sorted(out.items(), key=lambda kv: (-kv[1][0], kv[1][1]))]


def _lyrics_languages(text):
    """{language code: share} for a lyric text (script-based for non-Latin
    scripts, common-word counts for Latin-script languages); {} when too short."""
    t = str(text or "")
    letters = len(re.findall(r"[^\W\d_]", t))
    if letters < 12:
        return {}
    shares = {}
    for code, rx in _SCRIPT_LANGS:
        n = len(re.findall(rx, t))
        if letters and n / letters >= 0.05:
            shares[code] = n / letters
    if shares.get("ja") and shares.get("zh"):        # kanji inside Japanese
        shares["ja"] += shares.pop("zh")
    latin = 1.0 - min(1.0, sum(shares.values()))
    words = re.findall(r"[a-zà-ÿßæøåœçñ']+", t.lower())
    if words and latin > 0.05:
        hits = {k: sum(1 for w in words if w in s) for k, s in _LANG_STOPSETS.items()}
        tot = sum(hits.values())
        if tot >= 8:
            for k, h in hits.items():
                if h / tot >= 0.2:
                    shares[k] = shares.get(k, 0.0) + latin * h / tot
    return shares


def _lyrics_text_for_genre(text, meta):
    lyr = str((meta or {}).get("lyrics") or "").strip()
    if not lyr:
        m = re.search(r"LYRICS HEARD IN AUDIO[^\n]*\n([\s\S]{0,6000}?)(?:\n\n[A-Z][A-Z /&\-]{6,}|\Z)", str(text or ""))
        lyr = m.group(1) if m else ""
    title = str((meta or {}).get("title") or "")
    return (lyr + "\n" + title).strip()


def _artist_origin_lead(artist):
    """First sentence of the artist's article in the local Wikipedia copy, or ""
    (no copy, no clear match). Cached; never raises."""
    a = _wiki_clean_artist_for_search(artist) if artist else ""
    if not a:
        return ""
    if a in _ARTIST_ORIGIN_CACHE:
        return _ARTIST_ORIGIN_CACHE[a]
    lead = ""
    try:
        if _get_wiki_db() is not None:
            for title, body in _wiki_multi_search([a], max_articles=2) or []:
                tk = _wiki_fold_diacritics(re.sub(r"\s*\((?:band|singer|musician|rapper|group)\)$", "", str(title))).lower()
                if tk.strip() in (_wiki_fold_diacritics(a).lower().strip(), "the " + _wiki_fold_diacritics(a).lower().strip()):
                    b = re.sub(r"\s+", " ", str(body or ""))[:600]
                    lead = b.split(". ")[0][:400]
                    break
    except Exception:
        lead = ""
    _ARTIST_ORIGIN_CACHE[a] = lead
    return lead


def _origin_is(region, lead):
    """True when the article's first sentence calls the artist one of `region`'s nationalities."""
    rx = _REGION_ORIGIN.get(region)
    if not rx or not lead:
        return False
    return bool(re.search(r"\b(?:is|was|are|were)\s+(?:an?|the)\s+(?:[\w\-]+\s+){0,2}?(?:" + rx + r")\b", lead))


class _GenreContext:
    """What the regional check needs about one track: lyric languages and artist origin (lazy)."""

    def __init__(self, text, meta):
        self.meta = meta or {}
        self.langs = _lyrics_languages(_lyrics_text_for_genre(text, self.meta))
        # A title or album written in a non-Latin script ("Gangnam Style (강남스타일)")
        # counts as that language even when the lyrics are romanised.
        names = " ".join(str(self.meta.get(k) or "") for k in ("title", "album"))
        for code, rx in _SCRIPT_LANGS:
            if len(re.findall(rx, names)) >= 3:
                self.langs[code] = max(self.langs.get(code, 0.0), 0.5)
        if self.langs.get("ja") and self.langs.get("zh") and re.search(r"[\u3040-\u30ff]", names):
            self.langs["ja"] = max(self.langs["ja"], self.langs.pop("zh"))
        self._lead = None

    def lead(self):
        if self._lead is None:
            self._lead = _artist_origin_lead(self.meta.get("artist")) if REGIONAL_GENRE_GATE else ""
        return self._lead

    def non_english(self):
        if not self.langs:
            return False
        top = max(self.langs.items(), key=lambda kv: kv[1])[0]
        return top != "en"

    def region_ok(self, region):
        if not region:
            return True
        if any(self.langs.get(l, 0.0) >= 0.25 for l in _REGION_LANGS.get(region, ())):
            return True
        return _origin_is(region, self.lead())


def _regional_label_ok(label, ctx):
    """False for a World/International-type label, or a regional one this track does not qualify for."""
    if not REGIONAL_GENRE_GATE:
        return True
    n = _style_norm(label)
    if n in _WORLD_LABELS or re.search(r"\bworld\b|\binternational\b", n):
        return False
    region = _REGIONAL_STYLES.get(n) or _REGIONAL_TAGS.get(n)
    if not region:
        return True
    return ctx.region_ok(region) if ctx is not None else False


def _style_led_decision(rec, items, ranked_labels, panns, year, stock=False):
    """(new label, why) when the measured styles should lead the genre, else None."""
    if not items:
        return None
    l1, p1 = items[0]
    ft, fc = _style_families(l1), _style_families(rec)
    if not ft:
        return None
    onset = _genre_onset(l1)
    if year and onset and year < onset:
        return None                                      # a later label than the recording
    base = re.sub(r"\s*\(with .*?\)", "", str(rec)).strip()
    if ft & fc:
        broad = ("(with " in str(rec).lower() or _style_norm(rec) in {_style_norm(b) for b in _STYLE_BROAD_LABELS}
                 # a stock-list label is shown as its broad family (MOSS_LOW_TRUST_FIELDS)
                 or (stock and _style_norm(base) in _STYLE_TEMPLATE_LABELS))
        if broad and p1 >= GENRE_STYLE_REFINE_MIN and not (ft & _STYLE_NO_REFINE_FAMILIES):
            return l1, "refine"
        return None
    if p1 < GENRE_STYLE_REPLACE_MIN:
        return None
    if not any(_style_families(x) & ft for x in list(ranked_labels) + [t for t, p in panns if p >= 0.15]):
        return None                                      # no second source hears that family
    partial = any(_style_families(l) & fc for l, _p in items[1:3])
    if partial and _style_norm(base) not in _STYLE_TEMPLATE_LABELS:
        return None
    return l1, "replace"


def _style_led_genre_block(new, p, old, why):
    if why == "refine":
        how = f"it narrows the earlier '{old}' reading to the specific style"
    elif why == "regional":
        how = f"the earlier '{old}' label is a regional or World label this track does not qualify for"
    else:
        how = (f"it replaces the earlier '{old}' reading, which another measured source contradicts")
    return (f"RECOMMENDED GENRE FOR DISCUSSION: {new}. Reasoning: {_STYLE_LED_TAG} the recording's clearest "
            f"measured style is {new} ({p * 100:.0f}%); {how}. This is the primary genre framing for the user. "
            "Do not lead with a conflicting early GENRE_RANKED label when this block "
            "explicitly revises rock/punk vs electronic/dance identity.")


def _era_style_decision(era_text, items):
    """(label, prob, (start, end)) when a confident period-bound style contradicts the era estimate."""
    ds = [int(d) for d in re.findall(r"(\d{4})s", str(era_text or ""))]
    if not ds:
        return None
    lo, hi = min(ds), max(ds) + 9
    if hi < 2019:
        return None          # only the known failure: clean masters dated "2010s-2020s"
    for lab, p in items[:3]:
        per = _STYLE_PERIOD.get(_style_norm(lab))
        if per and per[1] - per[0] + 1 <= ERA_STYLE_MAX_SPAN and p >= ERA_STYLE_MIN:
            return (lab, p, per) if (per[1] < lo or per[0] > hi) else None
    return None


def _genre_style_view(text, meta=None, year=None):
    """dev44 first step of the chat model's view: regional styles gated, the
    style-led recommended genre, and the style era check. Unchanged text when
    there is nothing to do."""
    t = str(text or "")
    has_styles = bool(_STYLE_SIGNAL_HEARD_RE.search(t))
    recs = list(_RECOMMENDED_GENRE_RE.finditer(t))
    if not has_styles and not (REGIONAL_GENRE_GATE and recs):
        return t
    ctx = _GenreContext(t, meta) if REGIONAL_GENRE_GATE else None
    # 1. regional / World styles out of the styles line
    if has_styles and REGIONAL_GENRE_GATE:
        found = list(_STYLE_SIGNAL_HEARD_RE.finditer(t))
        m = found[-1]
        heard = m.group(1)
        if not heard.lower().startswith("none clear"):
            keep = []
            for part in heard.split(";"):
                mm = _STYLE_ITEM_RE.match(part)
                lab = _style_label(mm.group(1).strip(), mm.group(2).strip()) if mm else None
                if mm and lab is not None and not _regional_label_ok(lab, ctx):
                    continue
                keep.append(part.strip())
            new_heard = "; ".join(keep) if keep else "none clear"
            if new_heard != heard:
                t = t[:m.start(1)] + new_heard + t[m.end(1):]
    # 2. the recommended genre
    recs = list(_RECOMMENDED_GENRE_RE.finditer(t))
    if recs and _STYLE_LED_TAG not in t:
        rec = recs[-1].group(1).strip()
        items = _style_signal_items(t) if has_styles else []
        decision = None
        if GENRE_STYLE_LED and items:
            try:
                ranked = extract_genre_ranked_labels(t, max_n=8)
            except Exception:
                ranked = []
            try:
                stock = bool(MOSS_LOW_TRUST_FIELDS and _stock_genre_list(ranked))
            except Exception:
                stock = False
            decision = _style_led_decision(rec, items, ranked, _panns_genre_tags_from_text(t), year, stock=stock)
            if decision and not _regional_label_ok(decision[0], ctx):
                decision = None
        if decision is None and not _regional_label_ok(rec, ctx):
            alt = [(l, p) for l, p in items if _regional_label_ok(l, ctx)]
            if alt:
                decision = (alt[0][0], "regional")
            else:
                fam = _genre_family(rec)
                decision = ({"rockish": "rock", "electronicish": "electronic", "popish": "pop"}.get(fam, "pop"),
                            "regional")
        if decision:
            new, why = decision
            p = dict(items).get(new, 0.0)
            blk = re.compile(r"RECOMMENDED GENRE FOR DISCUSSION: " + re.escape(rec)
                             + r"\. Reasoning:[^\n]*")
            ms = list(blk.finditer(t))
            if ms:
                mm = ms[-1]
                t = t[:mm.start()] + _style_led_genre_block(new, p, rec, why) + t[mm.end():]
    # 3. the era estimate
    if ERA_STYLE_CHECK and has_styles and _ERA_CHECK_HEAD not in t:
        ms = list(re.finditer(r"(?m)^ERA_ESTIMATE=([^\n]*)$", t))
        items = _style_signal_items(t)
        if ms and items:
            m = ms[-1]
            d = _era_style_decision(m.group(1), items)
            if d:
                lab, p, per = d
                d0, d1 = per[0] // 10 * 10, per[1] // 10 * 10
                new = f"{d0}s" if d0 == d1 else f"{d0}s–{d1}s"
                note = (f"\n{_ERA_CHECK_HEAD} the era pass said '{m.group(1).strip()}', which reflects clean, "
                        f"modern-sounding production rather than the style: the clearest period-bound style heard, "
                        f"{lab} ({p * 100:.0f}%), belongs to about {per[0]}–{per[1]}, so the recording most "
                        f"likely dates from the {new}. A file's year tag or release information still comes first.")
                t = t[:m.start()] + f"ERA_ESTIMATE={new}" + note + t[m.end():]
    return t


def _world_label_view(text, meta=None):
    """dev44 last step of the chat model's view: World/International-type
    labels, and regional labels this track does not qualify for, are taken out
    of the PANNs tag line and the listening model's genre lists."""
    t = str(text or "")
    if not REGIONAL_GENRE_GATE:
        return t
    ctx = None

    def ok(lab):
        nonlocal ctx
        n = _style_norm(lab)
        if not (n in _WORLD_LABELS or _REGIONAL_STYLES.get(n) or _REGIONAL_TAGS.get(n)
                or re.search(r"\bworld\b|\binternational\b", n)):
            return True
        if ctx is None:
            ctx = _GenreContext(t, meta)
        return _regional_label_ok(lab, ctx)

    def tag_line(m):
        parts = re.split(r"(?<=%\)),\s*", m.group(2))
        keep = [p for p in parts if not re.match(r"\s*(.+?)\s*\(\d+(?:\.\d+)?%\)\s*$", p)
                or ok(re.match(r"\s*(.+?)\s*\(\d+(?:\.\d+)?%\)\s*$", p).group(1))]
        return m.group(1) + (", ".join(keep) if keep else "none")
    t = re.sub(r"(genre-adjacent tags:\s*)([^\n]+)", tag_line, t)

    def ranked_line(m):
        items = re.split(r";\s*(?=\d+\)\s*)", m.group(2))
        keep = []
        for it in items:
            mm = re.match(r"\s*\d+\)\s*([^(;]+)", it)
            if mm and not ok(mm.group(1).strip()):
                continue
            keep.append(re.sub(r"^\s*\d+\)\s*", "", it))
        if len(keep) == len(items):
            return m.group(0)
        return m.group(1) + "; ".join(f"{i}) {x}" for i, x in enumerate(keep, 1))
    t = re.sub(r"(GENRE_RANKED=)([^\n]+)", ranked_line, t)

    def list_line(m):
        items = [x for x in m.group(2).split(";")]
        keep = [x for x in items if ok(x.strip()) or not x.strip()]
        return m.group(0) if len(keep) == len(items) else m.group(1) + ";".join(keep).strip()
    t = re.sub(r"(GENRE_ADJACENT=)([^\n]+)", list_line, t)
    return t


def _regional_note(text, meta=None):
    """A sentence for the GENRE CONSISTENCY note about language and regional labels, or ""."""
    if not REGIONAL_GENRE_GATE:
        return ""
    ctx = _GenreContext(text, meta)
    out = ""
    if ctx.non_english():
        out += (" The lyrics are not mainly in English: never call the track world or international music "
                "because of its language -- the genre comes from how it sounds.")
    withheld = []
    fields = "\n".join(re.findall(r"(?m)^(?:GENRE_RANKED=|GENRE_ADJACENT=|styles heard:|genre-adjacent tags:|"
                                  r"RECOMMENDED GENRE FOR DISCUSSION:)[^\n]*", str(text or "")))
    for lab in dict.fromkeys(_style_norm(x) for x in re.findall(r"\b(K-pop|J-pop|C-pop|Cantopop|Mandopop|Europop|"
                                                               r"Eurodance|Britpop|Krautrock|Latin|Bollywood)\b", fields, re.I)):
        if not _regional_label_ok(lab, ctx):
            withheld.append(lab)
    if withheld:
        out += (" Do not call it " + " or ".join(f"'{w}'" for w in withheld[:3]) + ": regional labels like these "
                "are used only for songs sung in that language or by artists from that place.")
    return out


# --- dev45: chord progressions (lv-chordia) and the melody in the key ---------
# See ENABLE_CHORD_PROGRESSION and MELODY_IN_KEY_BY_SECTION.
_CHORD_REC_LOCK = threading.Lock()
_CHORD_REC_STATE = {"unavailable": None}
_CHORD_RESULTS = collections.OrderedDict()      # track path -> segments, for the save
_CP_HEAD = "CHORD PROGRESSION BY SECTION"
_MK_HEAD = "MELODY IN THE KEY BY SECTION"
_CP_QUALITY = {"maj": "", "min": "m", "7": "7", "maj7": "maj7", "min7": "m7", "dim": "dim", "aug": "aug",
               "sus2": "sus2", "sus4": "sus4", "sus4(b7)": "7sus4", "9": "9", "maj9": "maj9", "min9": "m9",
               "11": "11", "13": "13", "dim7": "dim7", "hdim7": "m7b5", "maj6": "6", "min6": "m6"}
_CP_MINORISH = {"min", "min7", "min9", "dim", "dim7", "hdim7", "min6"}
_CP_BASS_INTERVAL = {"2": 2, "b3": 3, "3": 4, "4": 5, "b5": 6, "5": 7, "#5": 8, "b6": 8, "6": 9, "bb7": 9,
                     "b7": 10, "7": 11, "9": 2}
_CP_ROMAN = {0: "I", 1: "bII", 2: "II", 3: "bIII", 4: "III", 5: "IV", 6: "#IV", 7: "V", 8: "bVI", 9: "VI",
             10: "bVII", 11: "VII"}
_CP_DIATONIC = {"major": {0: "maj", 2: "min", 4: "min", 5: "maj", 7: "maj", 9: "min", 11: "dim"},
                "minor": {0: "min", 2: "dim", 3: "maj", 5: "min", 7: "min", 8: "maj", 10: "maj"}}
_CP_ALSO_IN_KEY = {"minor": {7: "maj", 11: "dim"}}        # the harmonic-minor V and vii
_CP_SHARP = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]
_CP_FLAT = ["C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"]
_CP_FLAT_KEYS = {("major", 5), ("major", 10), ("major", 3), ("major", 8), ("major", 1), ("major", 6),
                 ("minor", 2), ("minor", 7), ("minor", 0), ("minor", 5), ("minor", 10), ("minor", 3)}
_CP_ROOT_PC = {"C": 0, "C#": 1, "Db": 1, "D": 2, "D#": 3, "Eb": 3, "E": 4, "F": 5, "F#": 6, "Gb": 6, "G": 7,
               "G#": 8, "Ab": 8, "A": 9, "A#": 10, "Bb": 10, "B": 11, "Cb": 11, "Fb": 4, "E#": 5, "B#": 0}
_MK_DEGREE = {0: "1", 1: "b2", 2: "2", 3: "b3", 4: "3", 5: "4", 6: "#4", 7: "5", 8: "b6", 9: "6", 10: "b7",
              11: "7"}


def chord_segments_for(audio_path):
    """[[start, end, label]] from lv-chordia ("A:maj", "D:maj/3", "N"), or [] when
    disabled, not installed or failed. CPU only; never raises. A first failure to
    import or load is not retried in this session."""
    if not ENABLE_CHORD_PROGRESSION or not audio_path or str(audio_path).startswith(("http://", "https://")):
        return []
    if _CHORD_REC_STATE["unavailable"]:
        return []
    try:
        with _CHORD_REC_LOCK:
            try:
                import importlib
                _lvc = importlib.import_module("lv_chordia.chord_recognition")   # the module, not the function
            except Exception as e:
                _CHORD_REC_STATE["unavailable"] = str(e) or type(e).__name__
                print("  (chord progressions skipped for this session -- install the chord model once with "
                      f"'pip install lv-chordia': {_CHORD_REC_STATE['unavailable'][:160]})")
                return []
            _lvc.print = lambda *a, **k: None        # its per-model progress lines
            res = _lvc.chord_recognition(os.path.abspath(str(audio_path)), CHORD_PROGRESSION_DICTIONARY)
        out = []
        for x in res or []:
            try:
                s, e, lab = float(x["start_time"]), float(x["end_time"]), str(x["chord"])
            except Exception:
                continue
            if e > s:
                out.append([round(s, 2), round(e, 2), lab])
        return out
    except Exception as e:
        print(f"  (chord progressions skipped: {str(e).strip()[:160] or type(e).__name__})")
        return []


def _chord_remember(track_path, segs):
    if not segs or not track_path:
        return
    _CHORD_RESULTS[str(track_path)] = segs
    _CHORD_RESULTS.move_to_end(str(track_path))
    while len(_CHORD_RESULTS) > 16:
        _CHORD_RESULTS.popitem(last=False)


def _chord_segments_for_save(segs, track_key=None):
    """The saved form ([[start, end, label]]), from `segs` or the remembered result."""
    src = segs if segs else (_CHORD_RESULTS.get(str(track_key)) if track_key else None)
    out = []
    for it in src or []:
        try:
            out.append([round(float(it[0]), 2), round(float(it[1]), 2), str(it[2])])
        except Exception:
            continue
    return out


def _cp_parse(label):
    """(root pc, quality, bass pc or None) from "A:maj/3"; None for no chord."""
    lab = str(label or "").strip()
    if not lab or lab in ("N", "X") or ":" not in lab:
        return None
    root, _, rest = lab.partition(":")
    pc = _CP_ROOT_PC.get(root)
    if pc is None:
        return None
    qual, _, bass = rest.partition("/")
    if qual not in _CP_QUALITY:
        return None
    bpc = None
    if bass:
        iv = _CP_BASS_INTERVAL.get(bass)
        if iv is not None and iv != 0:
            bpc = (pc + iv) % 12
    return (pc, qual, bpc)


def _cp_key(key_text):
    k = _parse_key_root_quality(key_text) if key_text else None
    return k  # (root pc, "major"/"minor") or None


def _cp_name(ch, key):
    names = _CP_FLAT if key and (key[1], key[0]) in _CP_FLAT_KEYS else _CP_SHARP
    pc, qual, bpc = ch
    s = names[pc] + _CP_QUALITY.get(qual, "")
    return s + ("/" + names[bpc] if bpc is not None else "")


def _cp_roman(ch, key):
    pc, qual, _b = ch
    iv = (pc - key[0]) % 12
    r = _CP_ROMAN[iv]
    head = r.lstrip("b#")
    acc = r[: len(r) - len(head)]
    if qual in _CP_MINORISH:
        head = head.lower()
    suf = {"dim": "o", "dim7": "o7", "hdim7": "ø7", "aug": "+", "7": "7",
           "maj7": "maj7", "min7": "7", "9": "9", "maj9": "maj9", "min9": "9", "11": "11", "13": "13",
           "sus2": "sus2", "sus4": "sus4", "sus4(b7)": "7sus4", "maj6": "6", "min6": "6"}.get(qual, "")
    return acc + head + suf


def _cp_in_key(ch, key):
    pc, qual, _b = ch
    iv = (pc - key[0]) % 12
    want = _CP_DIATONIC[key[1]].get(iv) or _CP_ALSO_IN_KEY.get(key[1], {}).get(iv)
    if want is None:
        return False
    if qual.startswith("sus") or qual in ("aug",):
        return True
    fam = "dim" if qual in ("dim", "dim7", "hdim7") else ("min" if qual in _CP_MINORISH else "maj")
    if want == "dim":
        return fam in ("dim", "min")
    return fam == want or (key[1] == "minor" and iv in _CP_ALSO_IN_KEY["minor"])


def _cp_section_seq(segs, a, b, beat):
    """[(chord, duration)] in time order inside [a, b): repeats merged, slivers dropped."""
    pieces = []
    for s, e, ch in segs:
        if e <= a or s >= b:
            continue
        s2, e2 = max(s, a), min(e, b)
        if e2 - s2 >= 0.15:
            pieces.append([ch, e2 - s2])
    short = max(0.35, 0.5 * beat)
    for _ in range(2):
        merged = []
        for ch, d in pieces:
            if merged and merged[-1][0] == ch:
                merged[-1][1] += d
            else:
                merged.append([ch, d])
        pieces = [p for p in merged if p[1] >= short] if len(merged) > 1 else merged
    merged = []
    for ch, d in pieces:
        if merged and merged[-1][0] == ch:
            merged[-1][1] += d
        else:
            merged.append([ch, d])
    return [(ch, d) for ch, d in merged]


def _cp_loop(seq):
    """(pattern, repeats) for the shortest chord cycle covering 80%+ of the
    sequence at least twice, else None."""
    n = len(seq)
    for k in range(1, min(8, n // 2) + 1):
        best = None
        for off in range(k):
            pat = seq[off:off + k]
            if len(pat) < k:
                continue
            hits = sum(1 for i in range(n) if seq[i] == pat[(i - off) % k])
            if best is None or hits > best[0]:
                best = (hits, pat, off)
        if best and best[0] / float(n) >= 0.8 and n / float(k) >= 2:
            pat, off = best[1], best[2]
            if off:          # show the cycle from its first full statement
                pat = seq[off:off + k]
            return pat, int(round(n / float(k)))
    return None


def _cp_rhythm(durs, bar):
    if not durs or not bar:
        return ""
    r = float(np.median(durs)) / bar
    if r < 0.4:
        return "the chords change every beat or two"
    if r < 0.75:
        return "about two chords per bar"
    if r < 1.5:
        return "about one chord per bar"
    if r < 3.0:
        return "about one chord every two bars"
    return "long, held chords"


_CP_TIMES = {2: "twice", 3: "three times", 4: "four times", 5: "five times", 6: "six times", 7: "seven times",
             8: "eight times"}


def build_chord_progression_block(segments, sections, key_text=None, bpm=None):
    """See ENABLE_CHORD_PROGRESSION. "" when there is nothing to say. Never raises."""
    try:
        if not segments or not sections:
            return ""
        key = _cp_key(key_text)
        segs = []
        for it in segments:
            try:
                ch = _cp_parse(it[2])
                if ch:
                    segs.append((float(it[0]), float(it[1]), ch))
            except Exception:
                continue
        if len(segs) < 2:
            return ""
        beat = 60.0 / float(bpm) if bpm and float(bpm) > 0 else 0.5
        bar = 4 * beat
        lines, loops = [], []
        for sec in sections:
            try:
                a, b = float(sec["start"]), float(sec["end"])
            except Exception:
                continue
            name = str(sec.get("name") or "").strip() or "Section"
            if b - a < 3.0 or name.lower().startswith("silence"):
                continue
            seq = _cp_section_seq(segs, a, b, beat)
            if not seq:
                lines.append(f"  {name} ({_seconds_to_mmss(a)}-{_seconds_to_mmss(b)}): no clear chords")
                continue
            chords = [c for c, _d in seq]
            durs = [d for _c, d in seq]
            lp = _cp_loop(chords)
            shown = lp[0] if lp else chords[:8]
            names = " - ".join(_cp_name(c, key) for c in shown)
            if lp and len(lp[0]) == 1:
                desc = f"stays on {names}"
            elif lp:
                desc = f"{names}, {_CP_TIMES.get(lp[1], str(lp[1]) + ' times')}"
            else:
                desc = names + (" ..." if len(chords) > 8 else "")
            if key:
                desc += " (" + " - ".join(_cp_roman(c, key) for c in shown) + (" ..." if not lp and len(chords) > 8
                                                                              else "") + ")"
            parts = [desc]
            rh = _cp_rhythm(durs, bar)
            if rh and len(chords) > 1:
                parts.append(rh)
            if key:
                out = []
                for c in dict.fromkeys(chords):
                    if not _cp_in_key(c, key):
                        out.append(f"{_cp_name(c, key)} ({_cp_roman(c, key)})")
                if out:
                    tot = sum(durs)
                    od = sum(d for c, d in seq if not _cp_in_key(c, key))
                    if tot and od / tot >= 0.6:
                        parts.append("most chords here lie outside the key (a key change or a modal passage)")
                    else:
                        parts.append("outside the key: " + ", ".join(out[:4]))
            if lp and len(lp[0]) > 1:
                loops.append(tuple(lp[0]))
            lines.append(f"  {name} ({_seconds_to_mmss(a)}-{_seconds_to_mmss(b)}): " + "; ".join(parts))
        if not lines:
            return ""
        head = (f"{_CP_HEAD} (measured with a chord-recognition model on the full mix, in TIME ORDER -- unlike the "
                "ranked chord lists elsewhere, this IS the progression; repeats of one cycle are folded into "
                "'..., N times'" + (f"; Roman numerals are against the recommended key, {key_text}" if key else "")
                + "; chord names can be off on dense or distorted mixes, so treat extensions such as 7ths and "
                "sus chords as likely rather than certain):")
        summary = ""
        if loops:
            canon = {}
            for lp in loops:
                rots = [lp[i:] + lp[:i] for i in range(len(lp))]
                c = min(rots, key=lambda r: [x[0] for x in r])
                canon.setdefault(c, []).append(lp)
            best = max(canon.items(), key=lambda kv: len(kv[1]))
            if len(best[1]) >= 2:
                lp = max(set(best[1]), key=best[1].count)
                summary = ("\n  Most common cycle: " + " - ".join(_cp_name(c, key) for c in lp)
                           + (" (" + " - ".join(_cp_roman(c, key) for c in lp) + ")" if key else "")
                           + f", in {len(best[1])} sections")
        return head + summary + "\n" + "\n".join(lines)
    except Exception:
        return ""


def _mk_phrases(lead):
    """Phrases (lists of (onset, midi)) from (onset, dur, midi) notes: very short notes
    dropped, a gap of 0.45 s or more starts a new phrase."""
    notes = sorted((on, d, m) for on, d, m in lead if d >= 0.08)
    out, cur, last_end = [], [], None
    for on, d, m in notes:
        if cur and last_end is not None and on - last_end >= 0.45:
            out.append(cur)
            cur = []
        cur.append((on, int(round(m))))
        last_end = on + d
    if cur:
        out.append(cur)
    return out


def _mk_degrees(phrase, tonic):
    seq = []
    for _on, m in phrase:
        dg = _MK_DEGREE[(m - tonic) % 12]
        if not seq or seq[-1] != dg:
            seq.append(dg)
    return seq


_MK_SCALE = {"major": {0, 2, 4, 5, 7, 9, 11}, "minor": {0, 2, 3, 5, 7, 8, 10}}
_MK_END_WORDS = {"1": "1 (the tonic: settled, finished-sounding)", "5": "5 (the fifth: open, unresolved)",
                 "3": "3 (the third: warm but not final)", "b3": "b3 (the minor third: unsettled)"}


def _build_melody_in_key_by_section(sections, stem_notes, key=None, instrumental=False, context_text=""):
    """See MELODY_IN_KEY_BY_SECTION. "" when there is nothing to say. Never raises.
    Only statements that survive transcription slips are made: the degrees the
    held notes centre on, where phrases come to rest and the highest note."""
    if not MELODY_IN_KEY_BY_SECTION or not sections or not stem_notes or not key:
        return ""
    try:
        kq = _parse_key_root_quality(key)
        if not kq:
            return ""
        tonic = kq[0]
        scale = _MK_SCALE[kq[1]]
        pitched = {s_: _hm_pitched(stem_notes.get(s_)) for s_ in ("vocals", "bass") + _HM_ACC_STEMS}
        vocal_absent = _hm_vocal_absent(context_text)
        lines = []
        for sec in sections:
            try:
                a, b = float(sec["start"]), float(sec["end"])
            except Exception:
                continue
            name = str(sec.get("name") or "").strip() or "Section"
            if b - a < 3.0 or name.lower().startswith("silence"):
                continue
            lead_stem, lead = _hm_lead(pitched, a, b, instrumental, vocal_absent)
            if not lead:
                continue
            # Short notes, and short notes outside the key above all, are mostly transcription slips
            # (on the scanned library 69% of notes under 0.15 s fit the key, 90% of held ones).
            clean = [x for x in lead if x[1] >= 0.15 and (x[1] >= 0.25 or (int(round(x[2])) - tonic) % 12 in scale)]
            held = [x for x in clean if x[1] >= 0.25]
            if len(held) < 6:
                continue
            parts = ["the voice" if lead_stem == "vocals" else f"the {lead_stem} stem"]
            w = {}
            for on, d, m in held:
                dg = _MK_DEGREE[(int(round(m)) - tonic) % 12]
                w[dg] = w.get(dg, 0.0) + d
            tot = sum(w.values())
            fit = sum(d for _on, d, m in held if (int(round(m)) - tonic) % 12 in scale) / tot if tot else 0.0
            if fit < MELODY_IN_KEY_MIN_FIT:
                lines.append(f"  {name} ({_seconds_to_mmss(a)}-{_seconds_to_mmss(b)}): {parts[0]}; its held notes "
                             "do not sit clearly in the key here (a passing modulation, or an unreliable "
                             "transcription) -- describe this part by its contour only")
                continue
            top = [dg for dg, v in sorted(w.items(), key=lambda kv: -kv[1])[:3] if v / tot >= 0.15][:2]
            if top:
                parts.append("its held notes centre on " + " and ".join(top))
            ends = []
            for p in _mk_phrases(clean):
                if len(p) >= 3:
                    ends.append(_MK_DEGREE[(p[-1][1] - tonic) % 12])
            if len(ends) >= 3:
                tdg, cnt = max(((e, ends.count(e)) for e in set(ends)), key=lambda x: (x[1], x[0] == "1"))
                if cnt / float(len(ends)) >= 0.4:
                    parts.append("phrases mostly end on " + _MK_END_WORDS.get(tdg, tdg))
                elif ends.count("1") / float(len(ends)) < 0.15:
                    parts.append("phrases rarely come to rest on the key note")
            hi = max(held, key=lambda x: x[2])
            parts.append(f"peaks on {_MK_DEGREE[(int(round(hi[2])) - tonic) % 12]} ({_hm_name(hi[2])})")
            lines.append(f"  {name} ({_seconds_to_mmss(a)}-{_seconds_to_mmss(b)}): " + "; ".join(parts))
        if not lines or sum(1 for ln in lines if "do not sit clearly" not in ln) < max(1, len(lines) // 2):
            return ""          # most parts do not fit the key: the key or the transcription is in doubt
        root_name = (_CP_FLAT if (kq[1], kq[0]) in _CP_FLAT_KEYS else _CP_SHARP)[tonic]
        head = (f"{_MK_HEAD} (the lead line against the key, {key}: 1 = {root_name}; degrees are numbered against "
                "the major scale, so b3, b6 and b7 are the minor-key notes; from the longer, held notes of this "
                "recording's transcription -- short notes, often transcription slips, are left out -- so these are "
                "the line's resting points and peaks, not a note-by-note score):")
        return head + "\n" + "\n".join(lines)
    except Exception:
        return ""


def _with_dev45_blocks(data):
    """A saved scan with the MELODY IN THE KEY block (from its stored notes) and,
    when it holds chord segments, the CHORD PROGRESSION block -- placed after the
    HARMONY AND MELODY BY SECTION block. Unchanged when they are there already or
    cannot be built. Never raises."""
    try:
        if not isinstance(data, dict):
            return data
        a = str(data.get("analysis") or "")
        secs = data.get("structure_sections")
        if not a or not secs:
            return data
        keys = re.findall(r"RECOMMENDED KEY FOR DISCUSSION: ([^.(\n]+)", a)
        key = keys[-1].strip() if keys else data.get("key")
        add = []
        if CHORD_PROGRESSION_IN_SAVED and _CP_HEAD not in a and data.get("chord_segments"):
            blk = build_chord_progression_block(data.get("chord_segments"), secs, key, data.get("bpm"))
            if blk:
                add.append(blk)
        if MELODY_IN_KEY_BY_SECTION and _MK_HEAD not in a and data.get("stem_midi"):
            blk = _build_melody_in_key_by_section(
                secs, _json_notes_to_stem_notes(data.get("stem_midi")), key=key,
                instrumental=VOCAL_ARBITRATION_MARKER in a, context_text=a)
            if blk:
                add.append(blk)
        if MELODICISM_MEASURED and _ML_HEAD not in a and data.get("stem_midi"):
            _inp = ((data.get("structure_replay") or {}).get("inputs") or {})
            blk = _build_melodicism_block(
                secs, _json_notes_to_stem_notes(data.get("stem_midi")), lyric_chunks=_inp.get("lyric_chunks"),
                instrumental=VOCAL_ARBITRATION_MARKER in a, context_text=a)
            if blk:
                add.append(blk)
        if not add:
            return data
        s0, e0 = _hm_block_span(a)
        if s0 >= 0:
            a2 = a[:e0] + "\n\n" + "\n\n".join(add) + a[e0:]
        else:
            i = a.find("=== MELODIC ANALYSIS")
            a2 = (a[:i] + "\n\n".join(add) + "\n\n" + a[i:]) if i >= 0 else (a.rstrip() + "\n\n" + "\n\n".join(add))
        return dict(data, analysis=a2)
    except Exception:
        return data


